/bin/bash -lc "rea inspect-binary-layout ./original/entitlements.sqlite --format json; python -B - <<'PY'
from pathlib import Path
import sqlite3,re
p=Path('original/entitlements.sqlite'); b=p.read_bytes(); print(b[:100].hex());
for m in re.finditer(rb'[ -~]{5,}',b): print(m.start(),m.group())
try:
 c=sqlite3.connect(f'file:{p}?mode=ro&immutable=1',uri=True); print(c.execute('select * from sqlite_schema').fetchall());print(c.execute('pragma integrity_check').fetchall())
except sqlite3.Error as e: print(e)
PY"

